#include "linkedlist_module.h"
static void swapData(Node* a, Node* b) { Patient t = a->data; a->data = b->data; b->data = t; }
void insertionSort(PatientList& L, int key, long& comps) { Node* sortedHead = 0; Node* cur = L.head; while (cur) { Node* nxt = cur->next; bool atFront = !sortedHead; if (sortedHead) { comps++; if (cmpKey(sortedHead->data, cur->data, key) > 0) atFront = true; } if (atFront) { cur->next = sortedHead; sortedHead = cur; } else { Node* s = sortedHead; while (s->next) { comps++; if (cmpKey(s->next->data, cur->data, key) > 0) break; s = s->next; } cur->next = s->next; s->next = cur; } cur = nxt; } L.head = sortedHead; L.tail = L.head; while (L.tail && L.tail->next) L.tail = L.tail->next; }
void bubbleSort(PatientList& L, int key, long& comps) { if (L.size < 2) return; Node* lastSorted = 0; bool swapped; do { swapped = false; Node* c = L.head; while (c->next != lastSorted) { comps++; if (cmpKey(c->data, c->next->data, key) > 0) { swapData(c, c->next); swapped = true; } c = c->next; } lastSorted = c; } while (swapped); }
void selectionSort(PatientList& L, int key, long& comps) { for (Node* i = L.head; i && i->next; i = i->next) { Node* m = i; for (Node* j = i->next; j; j = j->next) { comps++; if (cmpKey(j->data, m->data, key) < 0) m = j; } if (m != i) swapData(i, m); } }
void runSort(PatientList& L, int algo, int key, long& comps) { if (algo == 0) insertionSort(L, key, comps); else if (algo == 1) bubbleSort(L, key, comps); else selectionSort(L, key, comps); }
static void doSort(int d, int key, int algo, bool show) { PatientList work; work.copyFrom(orig[d]); long comps = 0; auto s = Clock::now(); runSort(work, algo, key, comps); auto e = Clock::now(); double us = elapsedUs(s, e); logResult("LinkedList", DS_NAMES[d], "Sort", ALGO_NAMES[algo], KEY_NAMES[key], "Unsorted", us, comps, work.memoryBytes()); sortedData[d][key].copyFrom(work); hasSorted[d][key] = true; printSortRow(d, key, algo, work.size, us, comps, work.memoryBytes()); if (show) { cout << "\nAll records after sorting by " << KEY_NAMES[key] << ":\n"; printPatientHeader(); for (Node* c = work.head; c; c = c->next) printPatientRow(c->data); } }
void sortingMenu() { while (true) { cout << "\n--- LINKED LIST SORTING ---\n1. Sort one dataset (choose field + algorithm)\n2. Full benchmark (4 datasets x 3 fields x 3 algorithms)\n3. Back\n"; int c = askInt("Choice: ", 1, 3); if (c == 3) return; if (c == 1) { int d = pickDataset(false), key = pickKey(), algo = pickAlgo(); cout << "\n"; printSortHeader(); doSort(d, key, algo, true); } else { cout << "\n"; printSortHeader(); for (int d = 0; d < 4; d++) for (int k = 0; k < 3; k++) for (int a = 0; a < 3; a++) doSort(d, k, a, false); cout << "\nAll results saved to " << LOG_FILE << ".\n"; } } }
